L46_1 = "\236\138\164\237\130\164\235\132\136 \235\167\144\236\178\152\235\159\188 \236\151\172\234\184\180 \235\163\176 \236\156\132\235\176\152\235\143\132 \235\147\164\237\130\164\236\167\128\235\167\140 \236\149\138\236\156\188\235\169\180 \234\183\184\235\167\140\236\157\180\234\177\176\235\147\160. \235\161\156\235\185\132 \236\160\149\235\143\132\235\169\180 \236\139\160\236\130\172\236\160\129\236\157\180\236\167\128."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "\227\130\185\227\130\173\227\131\138\227\131\188\227\129\174\232\168\128\227\129\134\227\129\168\227\129\138\227\130\138\227\128\129\227\129\147\227\129\147\227\129\175\227\131\171\227\131\188\227\131\171\233\129\149\229\143\141\227\130\130\227\131\144\227\131\172\227\129\170\227\129\145\227\130\140\227\129\176\227\129\132\227\129\132\227\130\147\227\129\160\227\130\136\227\128\130\227\131\173\227\131\147\227\131\188\230\180\187\229\139\149\227\129\144\227\130\137\227\129\132\227\129\170\227\130\137\231\180\179\229\163\171\231\154\132\227\129\160\227\130\141\227\128\130"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Like Skinner said, it's okay as long as you don't get caught. Lobbying is pretty mild, to be honest."
L45_1.m_Talk_ENG = L46_1
