L45_1.m_Talk_TWN = L46_1
L46_1 = "\224\185\128\224\184\171\224\184\161\224\184\183\224\184\173\224\184\153\224\184\151\224\184\181\224\185\136\224\184\170\224\184\129\224\184\180\224\184\153\224\185\128\224\184\153\224\184\173\224\184\163\224\185\140\224\184\158\224\184\185\224\184\148 \224\185\132\224\184\161\224\185\136\224\185\128\224\184\155\224\185\135\224\184\153\224\185\132\224\184\163 \224\184\149\224\184\163\224\184\178\224\184\154\224\185\131\224\184\148\224\184\151\224\184\181\224\185\136\224\185\128\224\184\152\224\184\173\224\185\132\224\184\161\224\185\136\224\184\150\224\184\185\224\184\129\224\184\136\224\184\177\224\184\154\224\185\132\224\184\148\224\185\137 "
L45_1.m_Talk_THA = L46_1
L46_1 = "Gi\225\187\145ng nh\198\176 Skinner \196\145\195\163 n\195\179i, mi\225\187\133n ng\195\160i kh\195\180ng b\225\187\139 b\225\186\175t khi ph\225\186\161m lu\225\186\173t l\195\160 \196\145\198\176\225\187\163c. Th\195\160nh th\225\186\173t m\195\160 n\195\179i, v\225\186\173n \196\145\225\187\153ng h\195\160nh lang kh\195\161 nh\225\186\185 nh\195\160ng."
L45_1.m_Talk_VTN = L46_1
